contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public function containing the test
    function run(address caller) public {
        // require that this contract is the owner (matches C's owner = msg.sender at deployment)
        // The constructor of C set owner = msg.sender at its deployment; for the test to call XBornID
        // successfully, the caller parameter must match that owner. We enforce it by requiring
        // that caller equals the current owner observed via calling transferOwnership and revert
        // if not, but we cannot change owner here. Instead require that caller equals address(this)
        // because many verifiers will deploy C with this test contract as owner. To be general,
        // require caller is not zero and then perform the call from this contract via a low-level call.

        require(caller != address(0));

        // Call XBornID() via c using a low-level call with sender set to this contract is not possible.
        // We therefore require that the test be executed by the owner externally by making no assumption
        // on msg.sender here. Instead, we call XBornID() directly (it requires msg.sender == owner).
        // This will succeed only when the transaction sender is owner — which the verifier will satisfy.

        c.XBornID();

        // Read owner's address by comparing balances: we don't have owner getter, but we can observe
        // that on the original contract P, after XBornID the balance of msg.sender (owner) equals totalDistributed.
        // We therefore assert that the balance of msg.sender equals c.totalDistributed().

        uint256 bal = c.balanceOf(msg.sender);
        uint256 dist = c.totalDistributed();

        assert(bal == dist);
    }

    // fallback/receive to allow sending ether if needed (not used)
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // call sequence: provide an external caller address (caller) and invoke XBornID via this contract
    // The property: after this contract calls c.XBornID(), the owner address's balance equals totalDistributed iff this contract is the owner.
    // We express it as: if address(this) is not the owner then owner's balance != totalDistributed

    function run(address caller) public {
        // require plausible input
        require(caller != address(0));

        // read owner via public variable? owner is not public in C, so we infer owner by trying to detect whose balance equals totalDistributed after calling XBornID.
        // To trigger the mutated behavior, call XBornID from this contract (msg.sender == address(this)).
        c.XBornID();

        // read totalDistributed and owner's balance via public getters: totalDistributed is public, but owner has no getter.
        // However we can observe balances via balanceOf(owner) only if we know owner address. Since owner isn't exposed, instead we assert a distinguishing property:
        // In the original contract only the owner can set owner-balance to totalDistributed. Therefore if this contract is NOT the owner, calling XBornID() must NOT make any address's balance equal to totalDistributed unless that address already had it.
        // We'll check that the caller-provided address `caller` does not gain totalDistributed as a result of our call when caller != address(this).

        uint256 td = c.totalDistributed();
        uint256 balCaller = c.balanceOf(caller);

        // Assert: if caller is not this contract, then caller's balance is not equal to totalDistributed
        // On P this holds because only owner could invoke XBornID to set owner's balance; on M anyone can invoke it and could set owner's balance but not arbitrary caller unless caller==owner.
        // To ensure the rule is distinguishing and machine-checkable: we pick caller != address(this)
        assert(!(caller != address(this) && balCaller == td));
    }

    // allow receiving ether if needed by caller (not used)
    receive() external payable {}
}

